from __future__ import annotations

import logging

from taf.hw.pdu import BadPortNumber, BadResponse
from taf.hw.pdu.device_status import DeviceStatus
from taf.hw.pdu.devices.http_client import HttpPdu


class OrbisRestClientV07(HttpPdu):
    """Orbis REST client for PDU control.
    Only setting the state of a port is supported due to limitations of the hardware API.
    PDU port mapping: 1 -> AC1, 2 -> AC2, 3 -> DC1, 4 -> DC2."""

    def __init__(self, host: str, port: int | None = None):
        """
        :param host: a base url for Orbis API
        :param port: port number for Orbis API connection, defaults to None
        """
        super().__init__(host, timeout=20)
        port_suffix = f":{port}" if port is not None else ""
        self.base_url = f"http://{host}{port_suffix}"

    @property
    def _port_setting(self):
        return {DeviceStatus.OFF: "0", DeviceStatus.ON: "1"}

    def get_port_status(self, port):
        raise NotImplementedError("Operation not supported for this PDU")

    def _set_port_status(self, port, status):
        logging.info(f"HTTP: Setting port to {status}: {port}")
        request_url = self._build_request_url(port, status)
        response = self._send_request(request_url, method="PUT")
        return self._parse_response(response, port)

    def _build_request_url(self, port, status):
        port_name = self._port_mapping(int(port))
        return f"{self.base_url}/api/dutMove/v0/{port_name}/{self._port_setting[status]}"

    def _port_mapping(self, port):
        port_maping = {
            1: "AC1",
            2: "AC2",
            3: "DC1",
            4: "DC2",
        }

        if port not in port_maping:
            exc_msg = f"Port number is invalid: {port}.\nShould be one of {port_maping}"
            raise BadPortNumber(exc_msg)

        return port_maping[port]

    def _parse_response(self, response, port):
        error_codes = {
            400: "BAD_REQUEST",
            408: "REQUEST_TIMEOUT",
            503: "SERVICE_UNAVAILABLE",
        }

        if response.status_code != 200:
            error_name = error_codes.get(response.status_code, "UNKNOWN_ERROR")
            raise BadResponse(f"Error: {error_name}, Response: {response.text}")

        return True
